"""Parser for mini-SWE-agent trajectories."""

import re
from typing import List, Dict, Any
from .base_parser import BaseTrajectoryParser, TrajectoryStep, ActionKind
from .file_events import command_cwd, output_views, shell_events_with_outcome


class MiniSWEParser(BaseTrajectoryParser):
    """Parses linear message-history trajectories generated by mini-SWE-agent."""

    _FENCE_RE = re.compile(r"```(?:bash|sh|shell|console)?\s*\n(.*?)```", re.S)
    _RC_RE = re.compile(r"<returncode>(-?\d+)</returncode>")
    # mini-swe-agent's own action rule: a ```bash block closed by a fence on
    # its own line. A block closed any other way is a format error.
    _ACTION_RE = re.compile(r"```bash\s*\n(.*?)\n```", re.S)
    _FORMAT_ERROR = "Please always provide EXACTLY ONE action"

    def _fenced_commands(self, content: str) -> str:
        """The shell commands in a turn, or empty when the turn issues none."""
        blocks = self._FENCE_RE.findall(content or "")
        return "\n".join(b.strip() for b in blocks)

    def parse_trajectory(self, raw_data: Any, manifest_item: Dict[str, Any]) -> List[TrajectoryStep]:
        steps: List[TrajectoryStep] = []
        messages = raw_data.get("messages", [])

        # Collect ground-truth failure annotations
        incorrect_steps = set()
        unuseful_steps = set()
        for stage in manifest_item.get("incorrect_stages", []):
            incorrect_steps.update(stage.get("incorrect_step_ids", []))
            unuseful_steps.update(stage.get("unuseful_step_ids", []))

        step_counter = 0
        # Script files the agent created, by path; running one writes what
        # its text writes (file_events._events_with_verbs).
        scripts: Dict[str, str] = {}
        i = 0
        while i < len(messages):
            msg = messages[i]
            role = msg.get("role", "")
            content = msg.get("content", "")

            # mini-SWE-agent actions are typically in assistant messages
            if role == "assistant":
                step_counter += 1
                action_raw = content.strip()
                # Only the fenced command is a command. A mini-SWE-agent turn is
                # prose followed by a ```bash block, and passing the whole turn
                # to the bash extractor made it mine the prose for filenames:
                # an arrow in "did_you_mean -> String" parsed as a redirection,
                # and words like "bash", "for" and "String" became tracked
                # files. Over the sampled corpus only 1 of 46 detected hazards
                # named a real path before this.
                kind, reads, writes = self.extract_bash_file_operations(
                    self._fenced_commands(action_raw))

                # Look ahead for environment observation
                obs_raw = ""
                if i + 1 < len(messages) and messages[i + 1].get("role") in ["user", "tool"]:
                    obs_raw = messages[i + 1].get("content", "")
                obs_text = obs_raw if isinstance(obs_raw, str) else str(obs_raw)

                # mini-swe-agent executes a turn only when it holds exactly
                # one fenced block; with none or several it replies with a
                # format error and runs nothing.
                blocks = self._ACTION_RE.findall(action_raw)
                rc_m = self._RC_RE.search(obs_text)
                ran = len(blocks) == 1 and self._FORMAT_ERROR not in obs_text
                # Each action runs in a fresh subprocess at the repository root,
                # so a `cd` lasts only for the command that makes it.
                events = (shell_events_with_outcome(blocks[0].strip(), obs_text,
                                                    int(rc_m.group(1)) if rc_m else None, cwd="",
                                                    scripts=scripts)
                          if ran else [])
                shown = output_views(obs_text, cwd=command_cwd(blocks[0].strip(), "")) if ran else []

                step = TrajectoryStep(
                    step_id=step_counter,
                    action_raw=action_raw,
                    action_kind=kind,
                    target_files_read=reads,
                    target_files_written=writes,
                    observation_raw=obs_raw,
                    is_incorrect=(step_counter in incorrect_steps),
                    is_unuseful=(step_counter in unuseful_steps),
                    token_count_estimate=self.estimate_tokens(action_raw + obs_text),
                    metadata={"framework": "mini-SWE-agent", "index": i},
                    events=events,
                    output_reads=shown,
                )
                steps.append(step)
            i += 1

        return self.canonicalize_paths(steps, manifest_item)
